OwnedPtr<FuncParam> CreateFuncParamForOptional(const FuncParam& param)
{
    auto pa = MakeOwned<FuncParam>();
    pa->identifier = param.identifier;
    pa->begin = param.begin;
    pa->type = ASTCloner::Clone<Type>(param.type.get());
    pa->ty = param.ty;
    pa->curFile = param.curFile;
    pa->end = param.end;
    pa->EnableAttr(Attribute::COMPILER_ADD);
    CopyNodeScopeInfo(pa.get(), &param);
    return pa;

Ptr<Ty> TypeChecker::TypeCheckerImpl::SynFuncParam(ASTContext& ctx, FuncParam& fp)
{
    if (!fp.type && !Ty::IsTyCorrect(fp.ty)) {
        return TypeManager::GetInvalidTy();
    }
    if (fp.type) {
        (void)Synthesize(ctx, fp.type.get());
        if (!Ty::IsTyCorrect(fp.type->ty)) {
            (void)Synthesize(ctx, fp.assignment.get()); // If fp has assignment, synthesize to report error.
            return TypeManager::GetInvalidTy();
        }
        fp.ty = fp.type->ty;
    }
    if (fp.assignment) {
        if (!Check(ctx, fp.ty, fp.assignment.get())) {
            return TypeManager::GetInvalidTy();
        }
        (void)Synthesize(ctx, fp.desugarDecl.get());
    }

    if (!Is<ClassDecl>(re.refFuncBody->parentClassLike)) {
        if (auto ctt = DynamicCast<ClassThisTy*>(re.expr->ty); ctt && ctt->decl) {
            re.expr->ty = ctt->decl->ty;
        }
    }

    // Generic decls imported from foreign code and created by auto-sdk have no body, no need to check return.
    if (!isWellTyped && NeedCheckBodyReturn(*re.refFuncBody)) {
        re.ty = TypeManager::GetInvalidTy();
    } else {
        re.ty = TypeManager::GetNothingTy();
    }

    return re.ty;
}
